  const sets = arr.map((s) => new Set([...s]));

  for (let i = 0; i < sets.length; i++) {
    for (let j = i + 1; j < sets.length; j++) {
      if (disjoint(sets[i], sets[j])) {
        ans = Math.max(ans, arr[i].length * arr[j].length);
      }
